INSERT OR REPLACE INTO clinical_graph_nodes VALUES
('PATH-RLL-PNEUMO', 'Pathology', 'Right Lower Lobe Alveolar Consolidation & Parapneumonic Effusion', 'ICD-10: J18.1 / J90', 'ELEVATED', 'LEVEL_1A', 'ATS/IDSA Community-Acquired Pneumonia Guidelines (NEJM / AJRCCM)', 'Dense airspace opacification in the right lower lobe with air bronchograms and meniscus blunting of the right lateral costophrenic sulcus.'),
('PATH-TIB-ORIF', 'Pathology', 'Schatzker II Lateral Tibial Plateau ORIF — Hardware & Subchondral Audit', 'ICD-10: S82.121D / Z96.65', 'ROUTINE', 'LEVEL_1B', 'AO Trauma Foundation / OTA Proximal Tibia Fixation Standards', 'Post-operative anatomic reduction of lateral split-depression tibial plateau fracture stabilized with periarticular locking buttress plate and 5 bicortical/rafting screws.'),
('PATH-ACUTE-SDH', 'Pathology', 'Acute Left Frontoparietal Convexity Subdural Hematoma with Mass Effect', 'ICD-10: S06.5X0A', 'CRITICAL', 'LEVEL_1A', 'Brain Trauma Foundation (BTF) 4th Edition Neurosurgical Guidelines', 'Hyperdense crescentic extra-axial collection (68–76 HU) along the left cerebral hemisphere causing sulcal effacement, ipsilateral lateral ventricular compression, and 6.4mm rightward subfalcine midline shift.'),
('ANAT-RLL-PLEURA', 'AnatomicalSite', 'Right Lower Pulmonary Lobe (Segments S8–S10) & Costophrenic Recess', 'SNOMED: 41224006', NULL, 'PEER_REVIEWED', 'Felson Principles of Chest Roentgenology', 'Posterior and lateral basal bronchopulmonary segments abutting the right hemidiaphragm and parietal pleura.'),
('ANAT-LAT-TIB-PLATEAU', 'AnatomicalSite', 'Lateral Tibial Condyle, Subchondral Articular Cortex & Proximal Metaphysis', 'SNOMED: 12611008', NULL, 'PEER_REVIEWED', 'Rockwood and Green Fractures in Adults', 'Weight-bearing lateral femorotibial compartment supporting axial knee kinematics and submeniscal load transmission.'),
('ANAT-LEFT-SUBDURAL', 'AnatomicalSite', 'Left Frontoparietal Subdural Space, Bridging Cortical Veins & Falx Cerebri', 'SNOMED: 55641003', NULL, 'PEER_REVIEWED', 'Osborn Brain: Imaging, Pathology, and Anatomy', 'Potential space between the inner dural border cell layer and arachnoid membrane traversed by parasagittal bridging veins.'),
('PROT-CAP-PLEURAL-US', 'StandardProtocol', 'Empiric Beta-Lactam + Macrolide Regimen & Point-of-Care Thoracic Ultrasound', 'ACR-CAP-2025', NULL, 'LEVEL_1A', 'IDSA/ATS Consensus Guidelines & British Thoracic Society Pleural Disease Protocol', 'Initiate IV Ceftriaxone + Azithromycin within 4 hours; perform bedside pleural ultrasound to quantify septations and perform diagnostic thoracentesis if fluid thickness > 15mm.'),
('PROT-ORTHO-WBAT-REHAB', 'StandardProtocol', 'Protected Toe-Touch Weight Bearing (TTWB) & Early Passive ROM Protocol', 'AO-ORIF-TIB-04', NULL, 'LEVEL_1B', 'Journal of Orthopaedic Trauma Post-ORIF Rehabilitation Consensus', 'Maintain hinged knee brace with progressive passive flexion (0–90 deg) and strict toe-touch weight bearing (10–15 kg max) for 6 weeks until cortical bridging callus matures.'),
('PROT-NEURO-CRANIOTOMY', 'StandardProtocol', 'STAT Neurosurgical Decompressive Craniotomy Evaluation & Hyperosmolar ICP Control', 'BTF-SDH-STAT-01', NULL, 'LEVEL_1A', 'Brain Trauma Foundation Surgical Management of Acute Subdural Hematomas', 'Immediate neurosurgical evacuation required for acute SDH thickness > 10mm or midline shift > 5mm regardless of GCS. Administer IV Hypertonic Saline (3%) or Mannitol and reverse anticoagulants.'),
('CONTRA-BLIND-TAP', 'Contraindication', 'Avoid Un-Guided Blind Pleural Tap or Delayed Antibiotic Initiation (>4h)', 'SAFETY-THOR-09', 'ELEVATED', 'LEVEL_1A', 'BTS Pleural Procedures Safety Alert', 'Blind intercostal needle aspiration without ultrasound localization increases iatrogenic pneumothorax risk by 4.2x.'),
('CONTRA-EARLY-FULL-WB', 'Contraindication', 'Contraindicated: Premature Full Axial Weight-Bearing (<6 Weeks) or High-Dose NSAIDs', 'SAFETY-ORTHO-14', 'ELEVATED', 'LEVEL_1B', 'AAOS Clinical Practice Guideline on Fracture Nonunion Prevention', 'Unprotected full axial loading prior to metaphyseal trabecular consolidation risks secondary articular depression (>2mm) and proximal locking screw toggle.'),
('CONTRA-LUMBAR-PUNCTURE', 'Contraindication', 'STRICT CONTRAINDICATION: Lumbar Puncture, Hypotonic IV Fluids & Anticoagulants', 'SAFETY-NEURO-01', 'CRITICAL', 'LEVEL_1A', 'Neurocritical Care Society Emergency Herniation Prevention Standard', 'Lumbar puncture is strictly contraindicated in the presence of 6.4mm midline shift and basal cistern effacement due to lethal uncal/tonsillar herniation risk.'),
('HIST-PREC-CAP-COHORT', 'HistoricalPrecedent', 'Multi-Center Thoracic Cohort (n=1,420): Early US-Guided Effusion Triage Cut ICU Transfer by 38%', 'COHORT-THOR-2024', NULL, 'LEVEL_2A', 'Indian Journal of Radiology and Imaging / Lancet Respiratory Cohort', 'Patients with RLL consolidation + blunted costophrenic angle >15mm who received early ultrasound stratification avoided late empyema decortication in 91.4% of cases.'),
('HIST-PREC-ORIF-COHORT', 'HistoricalPrecedent', 'AO Registry Precedent (n=890 Schatzker II): Subchondral Rafting Screws Preserved 94% 5-Yr Alignment', 'COHORT-ORTHO-2023', NULL, 'LEVEL_2A', 'AO Trauma International Registry & JBJS Clinical Series', 'Subchondral rafting screws positioned parallel to the lateral tibial plateau joint line with zero intra-articular breach showed 94.2% anatomical union at 12 weeks.'),
('HIST-PREC-SDH-GOLDEN-HOUR', 'HistoricalPrecedent', 'CRASH-3 / Neuro-Trauma Registry (n=2,150): Surgical Decompression <120 Min Cut Mortality by 52%', 'COHORT-NEURO-2024', NULL, 'LEVEL_1A', 'New England Journal of Medicine / Lancet Neurology Trauma Audit', 'In acute subdural hematomas with >5mm midline shift, automated PACS critical-alert escalation reduced CT-to-incision time from 142 min to 48 min.');

