INSERT OR REPLACE INTO diagnostic_analyses VALUES
('ANL-CASE-1', 'case-1', 'PATH-RLL-PNEUMO', 'ELEVATED', 93, 0, 'SafetyComplianceAgent verified full inspiratory expansion (9 posterior ribs visible), zero motion blur, and crisp spinous process centering.', 'Confluent right lower lobe alveolar consolidation with air bronchograms and a moderate right parapneumonic pleural effusion.', 'High-resolution PA thoracic radiograph demonstrates confluent homogeneous airspace opacification occupying the posterior and lateral basal segments (S8–S10) of the right lower lobe, accompanied by branching radiolucent air bronchograms.', 'No indwelling central venous catheters, pacemaker leads, or sternotomy wires present. Trachea is midline.', 1180),
('ANL-CASE-2', 'case-2', 'PATH-TIB-ORIF', 'ROUTINE', 96, 0, 'SafetyComplianceAgent verified orthogonal AP knee projection with minimal metallic beam-hardening scatter around the titanium locking plate.', 'Anatomic post-operative reduction of lateral tibial plateau fracture (Schatzker II) with intact periarticular locking plate and 5 bicortical screws; zero hardware loosening.', 'AP orthopedic radiograph of the knee demonstrates post-operative internal fixation of a lateral tibial plateau split-depression fracture utilizing a contoured lateral periarticular locking buttress plate and 5 transverse screws.', 'HARDWARE INTEGRITY: 1x 5-hole contoured titanium lateral proximal tibial locking plate + 5x 3.5mm/4.5mm screws. Zero screw back-out.', 1090),
('ANL-CASE-3', 'case-3', 'PATH-ACUTE-SDH', 'CRITICAL', 97, 0, 'SafetyComplianceAgent verified zero gantry motion artifact, symmetrical petrous bone alignment, and calibrated 40/80 HU brain parenchymal windowing.', 'CRITICAL STAT ALERT: Large acute left frontoparietal convexity subdural hematoma (14.2mm thickness) with ipsilateral ventricular compression and 6.4mm rightward subfalcine midline shift.', 'Non-contrast axial head CT demonstrates a large hyperdense (68–76 HU) crescent-shaped extra-axial hemorrhage layering along the left frontoparietal convexity.', 'PRE-OP NEUROSURGICAL STAT STATUS: Immediate neurosurgical decompression indicated per BTF guidelines.', 1140);

